            "Après le petit-déjeuner, embarquez pour une visite de la ville d'Almaty, explorant ses principaux points forts : le parc du Premier Président, la place de la République et le monument de l'Indépendance, le théâtre d'opéra et de ballet d'État, l'Académie des sciences et la place Abay et le palais de la République.Dans la soirée, prenez un téléphérique jusqu'à la colline Kok Tobe, le point culminant de la ville (1 100 m).Profitez d'une vue panoramique sur Almaty et ses montagnes environnantes.",
